#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');

const ACTION='honartik_iticket_dark_backend_batch2_v1';
const OPERATION='host_action.honartik_iticket_dark_backend_batch2_v1';
const VERSION='1.15.0-host-actions-v2-honartik-iticket-dark-backend-batch2-registration';
const POLICY_VERSION='2026-08-21.1-honartik-iticket-dark-backend-batch2-v1';
const HELPER_SHA='439f5589a33d8ac89760af63b4722fc081684e26ac720d8e31a8d2ba0a870a8a';
const HELPER_B64='';
const PATHS=Object.freeze({
  base:'/opt/prhm-agent-selfmaint/server.js',
  executor:'/opt/prhm-agent-selfmaint-exec/server.js',
  mcp:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',
  policy:'/opt/prhm-company-control-plane/config/approval-policy.json',
  helper:'/opt/prhm-agent-selfmaint-exec/actions/honartik-iticket-dark-backend-batch2-v1.js'
});
const SERVICES=Object.freeze(['prhm-company-approval.service','prhm-agent-selfmaint.service','prhm-agent-selfmaint-exec.service','prhm-agent-mcp.service']);
const LOCK='/run/lock/prhm-host-actions-v15-honartik-iticket-batch2-registration.lock';
