const JOURNAL=JOURNAL_DIR+'/install-state.json';

function fail(m){throw new Error(m)}
function sha(b){return crypto.createHash('sha256').update(b).digest('hex')}
function read(p){return fs.readFileSync(p)}
function regular(p){try{return fs.statSync(p).isFile()&&!fs.lstatSync(p).isSymbolicLink()}catch{return false}}
function unique(text,needle,label){const a=text.indexOf(needle);if(a<0)fail(label+'_missing');if(text.indexOf(needle,a+1)>=0)fail(label+'_duplicate');return a}
function atomicWrite(p,bytes,mode){fs.mkdirSync(path.dirname(p),{recursive:true,mode:0o755});const t=p+'.tmp-'+process.pid+'-'+Date.now();fs.writeFileSync(t,bytes,{mode});fs.renameSync(t,p);fs.chmodSync(p,mode)}
function verifyEmbeddedHelper(){const b=Buffer.from(HELPER_B64,'base64');if(sha(b)!==HELPER_SHA)fail('embedded_helper_sha_mismatch');return true}
function helperBytes(){verifyEmbeddedHelper();return Buffer.from(HELPER_B64,'base64')}

function patchBase(source){
  if(source.includes(ACTION))fail('base_action_already_present');
  const marker="  honartik_iticket_dark_backend_batch1_v1: { operation: 'host_action.honartik_iticket_dark_backend_batch1_v1', rollback: 'host-action-v2:honartik-iticket-dark-backend-batch1-v1:worktree-file-rollback' },";
  unique(source,marker,'base_batch1_anchor');
  return source.replace(marker,marker+"\n  "+ACTION+": { operation: '"+OPERATION+"', rollback: 'host-action-v2:honartik-iticket-dark-backend-batch2-v1:worktree-file-rollback' },");
}
function patchMcp(source){
  if(source.includes("'"+ACTION+"'"))fail('mcp_action_already_present');
  const start='const HostActionV2=z.enum([';const s=source.indexOf(start);if(s<0||source.indexOf(start,s+1)>=0)fail('mcp_enum_anchor_invalid');
  const e=source.indexOf(']);',s);if(e<0)fail('mcp_enum_end_missing');
  const body=source.slice(s,e);const marker="'honartik_iticket_dark_backend_batch1_v1'";const rel=body.indexOf(marker);
  if(rel<0)fail('mcp_batch1_anchor_missing');if(body.indexOf(marker,rel+1)>=0)fail('mcp_batch1_anchor_duplicate');
  const at=s+rel+marker.length;return source.slice(0,at)+",'"+ACTION+"'"+source.slice(at);
}
function executorApplyBlock(){return `
const HONARTIK_ITICKET_BATCH2_HELPER='${PATHS.helper}';
const HONARTIK_ITICKET_BATCH2_RESULT_DIR='/var/lib/prhm-agent-selfmaint-exec/honartik-iticket-dark-backend-batch2-v1';
const HONARTIK_ITICKET_BATCH2_RESULT=HONARTIK_ITICKET_BATCH2_RESULT_DIR+'/latest.json';
function applyHonartikIticketDarkBackendBatch2V1(){
  if(!fs.existsSync(HONARTIK_ITICKET_BATCH2_HELPER))throw new Error('honartik_iticket_batch2_helper_missing');
  ensureDir(HONARTIK_ITICKET_BATCH2_RESULT_DIR,0o700);
  try{if(fs.existsSync(HONARTIK_ITICKET_BATCH2_RESULT))fs.unlinkSync(HONARTIK_ITICKET_BATCH2_RESULT)}catch{}
  const unit='prhm-honartik-iticket-dark-backend-batch2-'+Date.now();
  const args=['--wait','--collect','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=PrivateDevices=true','--property=ProtectSystem=strict','--property=ProtectHome=read-only','--property=ProtectKernelTunables=true','--property=ProtectKernelModules=true','--property=ProtectControlGroups=true','--property=RestrictAddressFamilies=AF_UNIX','--property=CapabilityBoundingSet=CAP_DAC_OVERRIDE','--property=AmbientCapabilities=','--property=RestrictNamespaces=true','--property=ReadWritePaths=/home/honartik/worktrees/iticket-dark-v1-back '+HONARTIK_ITICKET_BATCH2_RESULT_DIR,'--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',HONARTIK_ITICKET_BATCH2_HELPER];
  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:180000});
  if(!fs.existsSync(HONARTIK_ITICKET_BATCH2_RESULT))throw new Error('honartik_iticket_batch2_result_missing');
  const result=readJson(HONARTIK_ITICKET_BATCH2_RESULT);
  const markers=['ITICKET_DARK_GATE_TEST=PASS','ITICKET_BATCH2_DARK_NETWORK_TEST=PASS','ITICKET_CATALOG_ADAPTER_TEST=PASS','ITICKET_SCHEDULE_ADAPTER_TEST=PASS','ITICKET_SEAT_ADAPTER_TEST=PASS','ITICKET_RESELLER_ORDER_ADAPTER_TEST=PASS'];
  if(result.ok!==true||result.schema_version!=='prhm.host-action-result.v1'||result.action!=='${ACTION}'||!Array.isArray(result.files)||result.files.length!==14||!Array.isArray(result.test_markers)||!markers.every(x=>result.test_markers.includes(x))||result.production_application_tree_mutation!==false||result.worktree_application_mutation!==true||result.git_metadata_mutation!==false||result.database_mutation!==false||result.deploy!==false||result.external_network!==false||result.token_read!==false||result.rollback?.performed!==false)throw new Error('honartik_iticket_batch2_result_invalid');
  return result;
}
`;}
function patchExecutor(source){
  if(source.includes("kind:'"+ACTION+"'"))fail('executor_action_already_present');
  const spec="  honartik_iticket_dark_backend_batch1_v1:{operation:'host_action.honartik_iticket_dark_backend_batch1_v1',kind:'honartik_iticket_dark_backend_batch1_v1'},";
  unique(source,spec,'executor_batch1_spec_anchor');
  let out=source.replace(spec,spec+"\n  "+ACTION+":{operation:'"+OPERATION+"',kind:'"+ACTION+"'},");
  const applyAnchor='function verifyProcessSandboxV2(){';unique(out,applyAnchor,'executor_apply_anchor');out=out.replace(applyAnchor,executorApplyBlock()+applyAnchor);
  const ds='applyHostActionV2=async function(action){';const start=unique(out,ds,'executor_dispatch_anchor');
  const fallback='return applyHostActionV2Original(action);};';const f=out.indexOf(fallback,start);if(f<0)fail('executor_dispatch_fallback_missing');
  out=out.slice(0,f)+"if(action==='"+ACTION+"')return applyHonartikIticketDarkBackendBatch2V1();"+out.slice(f);
  return out;
}
function patchPolicy(text){
  const p=JSON.parse(text);if(!p.operations||typeof p.operations!=='object'||!Array.isArray(p.typed_scopes))fail('policy_shape_invalid');
  if(!p.operations['host_action.honartik_iticket_dark_backend_batch1_v1'])fail('policy_batch1_operation_missing');
  if(!p.typed_scopes.some(x=>x&&x.action==='honartik_iticket_dark_backend_batch1_v1'))fail('policy_batch1_scope_missing');
  if(p.operations[OPERATION]||p.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_batch2_already_present');
  p.version=POLICY_VERSION;p.operations[OPERATION]={level:4};
  p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});
  return JSON.stringify(p,null,2)+'\n';
}
function buildPatchedFrom(x){const out={base:patchBase(x.base),executor:patchExecutor(x.executor),mcp:patchMcp(x.mcp),policy:patchPolicy(x.policy)};JSON.parse(out.policy);return out}
function verifyInputs(){for(const k of ['base','executor','mcp','policy'])if(!regular(PATHS[k]))fail('registration_input_invalid:'+k);verifyEmbeddedHelper()}
function buildPatched(){verifyInputs();return buildPatchedFrom({base:read(PATHS.base).toString('utf8'),executor:read(PATHS.executor).toString('utf8'),mcp:read(PATHS.mcp).toString('utf8'),policy:read(PATHS.policy).toString('utf8')})}
function systemctl(args){return cp.execFileSync('/usr/bin/systemctl',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:120000}).trim()}
function active(s){try{return systemctl(['is-active',s])==='active'}catch{return false}}
function preflight(){const p=buildPatched();return{ok:true,schema_version:'prhm.host-action-registration-preflight.v1',version:VERSION,action:ACTION,preflight_only:true,helper_sha256:HELPER_SHA,structural_anchors:true,control_plane_mutation:false,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false}}
function execute(){
  fs.mkdirSync(path.dirname(LOCK),{recursive:true});let lock;
  try{lock=fs.openSync(LOCK,'wx',0o600)}catch(e){fail('registration_lock_busy')}
  const originals={};const modes={};let mutated=false;
  try{
    const patched=buildPatched();for(const k of ['base','executor','mcp','policy']){originals[k]=read(PATHS[k]);modes[k]=fs.statSync(PATHS[k]).mode&0o777;}
    originals.helper=fs.existsSync(PATHS.helper)?read(PATHS.helper):null;modes.helper=fs.existsSync(PATHS.helper)?(fs.statSync(PATHS.helper).mode&0o777):0o700;
    fs.mkdirSync(JOURNAL_DIR,{recursive:true,mode:0o700});fs.writeFileSync(JOURNAL,JSON.stringify({phase:'prepared',action:ACTION,original_sha256:Object.fromEntries(Object.entries(originals).map(([k,v])=>[k,v===null?null:sha(v)]))})+'\n',{mode:0o600});
    for(const k of ['base','executor','mcp','policy'])atomicWrite(PATHS[k],Buffer.from(patched[k],'utf8'),modes[k]);atomicWrite(PATHS.helper,helperBytes(),0o700);mutated=true;
    for(const s of SERVICES)systemctl(['restart',s]);for(const s of SERVICES)if(!active(s))fail('service_not_active:'+s);
    const result={ok:true,schema_version:'prhm.host-action-registration-result.v1',version:VERSION,action:ACTION,installed:true,helper_sha256:HELPER_SHA,control_plane_mutation:true,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false,rollback:{performed:false}};
    fs.writeFileSync(JOURNAL,JSON.stringify({phase:'committed',result})+'\n',{mode:0o600});return result;
  }catch(e){
    if(mutated){for(const k of ['base','executor','mcp','policy'])if(originals[k])atomicWrite(PATHS[k],originals[k],modes[k]);if(originals.helper===null){try{fs.unlinkSync(PATHS.helper)}catch{}}else atomicWrite(PATHS.helper,originals.helper,modes.helper);for(const s of SERVICES){try{systemctl(['restart',s])}catch{}}}
    throw new Error('registration_failed'+(mutated?'_rolled_back':'')+':'+e.message);
  }finally{try{fs.closeSync(lock)}catch{}try{fs.unlinkSync(LOCK)}catch{}}
}
if(require.main===module){try{const pre=process.argv.includes('--preflight-only');process.stdout.write(JSON.stringify(pre?preflight():execute())+'\n')}catch(e){process.stderr.write(String(e.stack||e)+'\n');process.exitCode=1}}
module.exports={ACTION,OPERATION,VERSION,POLICY_VERSION,HELPER_SHA,verifyEmbeddedHelper,patchBase,patchExecutor,patchMcp,patchPolicy,buildPatchedFrom,preflight,execute};
